export type AutomationStatus = 'idle' | 'running' | 'success' | 'error';
export type AutomationConfig = Record<string, unknown>;

export type AutomationTypeDef = {
  type: string;
  label: string;
  execute(input: unknown, config: AutomationConfig): unknown;
};

export type AutomationNode = {
  id: string;
  type: string;
  config?: AutomationConfig;
};

export type AutomationEdge = { from: string; to: string };
export type AutomationWorkflow = { nodes: AutomationNode[]; edges: AutomationEdge[] };

export type AutomationNodeResult = {
  id: string;
  type: string;
  config: AutomationConfig;
  status: AutomationStatus;
  input?: unknown;
  output?: unknown;
  error?: string;
};

export type AutomationRunSummary = {
  status: 'success' | 'error';
  order: string[];
  output?: unknown;
  error?: string;
};

export type AutomationExecution = {
  nodes: AutomationNodeResult[];
  lastRun: AutomationRunSummary;
};

const configOf = (config: AutomationConfig | undefined) => ({ ...(config ?? {}) });

/** DOM-free workflow registry/executor. Server adapters can construct one per
 * tenant/request; the canvas plugin keeps one registry for its active session. */
export class AutomationBackend {
  readonly #types = new Map<string, AutomationTypeDef>();

  constructor(types: AutomationTypeDef[] = []) {
    types.forEach(type => { this.registerType(type); });
  }

  registerType(input: AutomationTypeDef): () => void {
    const type = input.type.trim();
    if (!type) throw new Error('Automation node type must not be empty.');
    const definition = { ...input, type };
    const previous = this.#types.get(type);
    this.#types.set(type, definition);
    return () => {
      if (this.#types.get(type) !== definition) return;
      if (previous) this.#types.set(type, previous);
      else this.#types.delete(type);
    };
  }

  types(): string[] {
    return [...this.#types.keys()];
  }

  execute(workflow: AutomationWorkflow): AutomationExecution {
    const nodes = workflow.nodes.map(node => ({ ...node, config: configOf(node.config) }));
    const byId = new Map(nodes.map(node => [node.id, node]));
    if (!nodes.length) {
      return {
        nodes: [],
        lastRun: { status: 'error', order: [], error: 'No automation nodes configured.' },
      };
    }

    const rank = new Map(nodes.map((node, index) => [node.id, index]));
    const incoming = new Map(nodes.map(node => [node.id, [] as string[]]));
    const outgoing = new Map(nodes.map(node => [node.id, [] as string[]]));
    workflow.edges.forEach(edge => {
      if (!byId.has(edge.from) || !byId.has(edge.to)) return;
      outgoing.get(edge.from)!.push(edge.to);
      incoming.get(edge.to)!.push(edge.from);
    });
    const indegree = new Map(nodes.map(node => [node.id, incoming.get(node.id)!.length]));
    const queue = nodes.filter(node => indegree.get(node.id) === 0).map(node => node.id);
    const results = new Map<string, AutomationNodeResult>();
    const order: string[] = [];
    let firstError = '';
    const sortQueue = () => queue.sort((a, b) => rank.get(a)! - rank.get(b)!);
    sortQueue();

    while (queue.length) {
      const id = queue.shift()!;
      order.push(id);
      const node = byId.get(id)!;
      const predecessors = incoming.get(id)!;
      const failedParent = predecessors.find(parent => results.get(parent)?.status === 'error');
      const inputs = predecessors.map(parent => results.get(parent)?.output);
      const input = inputs.length < 2 ? inputs[0] : inputs;
      if (failedParent) {
        const error = `Blocked by failed node ${failedParent}.`;
        results.set(id, { ...node, status: 'error', input, error });
        firstError ||= error;
      } else {
        const definition = this.#types.get(node.type);
        if (!definition) {
          const error = `Unknown automation node type: ${node.type}`;
          results.set(id, { ...node, status: 'error', input, error });
          firstError ||= error;
        } else {
          try {
            const output = definition.execute(input, configOf(node.config));
            if (output instanceof Promise) throw new Error('Async executors are not supported by this synchronous runner.');
            results.set(id, { ...node, status: 'success', input, output });
          } catch (cause) {
            const error = cause instanceof Error ? cause.message : String(cause);
            results.set(id, { ...node, status: 'error', input, error });
            firstError ||= error;
          }
        }
      }
      outgoing.get(id)!.forEach(next => {
        indegree.set(next, indegree.get(next)! - 1);
        if (indegree.get(next) === 0) queue.push(next);
      });
      sortQueue();
    }

    const unprocessed = nodes.filter(node => !results.has(node.id));
    if (unprocessed.length) {
      const error = `Workflow contains a cycle involving ${unprocessed.map(node => node.id).join(', ')}.`;
      unprocessed.forEach(node => results.set(node.id, { ...node, status: 'error', error }));
      firstError ||= error;
    }

    const sinks = nodes.filter(node => outgoing.get(node.id)!.length === 0);
    const lastSink = [...sinks].reverse().find(node => results.get(node.id)?.status === 'success');
    const lastRun: AutomationRunSummary = firstError
      ? { status: 'error', order, error: firstError }
      : { status: 'success', order, output: results.get(lastSink!.id)?.output };
    return {
      nodes: nodes.map(node => results.get(node.id)!),
      lastRun,
    };
  }
}

export const builtInAutomationTypes: AutomationTypeDef[] = [
  { type: 'manual', label: 'Manual Trigger', execute: (_input, config) => config.value },
  { type: 'set', label: 'Set Message', execute: (_input, config) => config.value },
  { type: 'uppercase', label: 'Uppercase', execute: input => String(input ?? '').toUpperCase() },
  { type: 'output', label: 'Output', execute: input => input },
];

export const createAutomationBackend = () => new AutomationBackend(builtInAutomationTypes);

/** Stateless convenience for HTTP/queue adapters that do not need a long-lived
 * custom type registry. */
export const executeAutomation = (workflow: AutomationWorkflow): AutomationExecution =>
  createAutomationBackend().execute(workflow);

import { nodeRef, type Registry } from '../core';
import type { Graph } from '../model';
import type { Id } from '../types';
import {
  createAutomationBackend,
  type AutomationConfig,
  type AutomationRunSummary,
  type AutomationStatus,
  type AutomationTypeDef,
} from '../../backend/automation';

export type {
  AutomationConfig,
  AutomationRunSummary,
  AutomationStatus,
  AutomationTypeDef,
} from '../../backend/automation';

export type AutomationNodeSnapshot = {
  id: Id;
  type: string;
  config: AutomationConfig;
  status: AutomationStatus;
  input?: unknown;
  output?: unknown;
  error?: string;
};

export type AutomationSnapshot = {
  types: string[];
  nodes: AutomationNodeSnapshot[];
  lastRun: AutomationRunSummary | null;
};

export type AutomationApi = {
  registerType(def: AutomationTypeDef): () => void;
  configure(nodeId: Id, type: string, config?: AutomationConfig): void;
  run(): AutomationRunSummary | null;
  reset(): void;
  snapshot(): AutomationSnapshot;
};

type StoredNode = { id: Id; type: string; config: AutomationConfig };
type StoredAutomation = { version: 1; nodes: StoredNode[] };
type Execution = {
  status: AutomationStatus;
  input?: unknown;
  output?: unknown;
  error?: string;
};
type GraphState = {
  nodes: Map<Id, StoredNode>;
  execution: Map<Id, Execution>;
  lastRun: AutomationRunSummary | null;
  snapshotOff: () => void;
};
type RestorableGraphState = Omit<GraphState, 'snapshotOff'>;

declare module '../types' {
  interface CustomEvents {
    'automation.node.configure': { id: Id; type: string; config?: AutomationConfig };
    'automation.node.updated': { graphId: Id; id: Id; type: string };
    'automation.example.create': void;
    'automation.example.created': { graphId: Id; ids: Id[] };
    'automation.run': void;
    'automation.run.changed': AutomationRunSummary & { graphId: Id };
    'automation.reset': void;
    'automation.reset.changed': { graphId: Id };
    'automation.inspector.open': void;
  }
  interface CustomExposable {
    automation?: AutomationApi;
  }
}

const cloneConfig = (config: AutomationConfig = {}) => ({ ...config });
const display = (value: unknown) => {
  if (typeof value === 'string') return value;
  if (value === undefined) return '';
  try { return JSON.stringify(value); } catch { return String(value); }
};

export function registerAutomation(system: Registry) {
  system('automation', (ctx) => {
    const { on, emit, graphs, contexts, contribute, declarePanel, origin } = ctx;
    const states = new Map<Id, GraphState>();
    const backend = createAutomationBackend();
    const registerType = (input: AutomationTypeDef) => backend.registerType(input);

    const restore = (state: RestorableGraphState, graph: Graph, value: StoredAutomation | undefined) => {
      state.nodes.clear();
      state.execution.clear();
      state.lastRun = null;
      if (value?.version !== 1 || !Array.isArray(value.nodes)) return;
      value.nodes.forEach(input => {
        if (!input?.id || !input.type || !graph.getNode(input.id)) return;
        state.nodes.set(input.id, { id: input.id, type: input.type, config: cloneConfig(input.config) });
      });
    };

    const ensureState = (graphId: Id) => {
      const existing = states.get(graphId);
      if (existing) return existing;
      const graph = graphs.get(graphId) ?? graphs.current;
      const saved = graph.snapshotExtension<StoredAutomation>('automation');
      const restorable: RestorableGraphState = {
        nodes: new Map(),
        execution: new Map(),
        lastRun: null,
      };
      restore(restorable, graph, saved);
      const snapshotOff = graph.registerSnapshotExtension<StoredAutomation>(
        'automation',
        () => ({
          version: 1,
          nodes: graph.nodes().flatMap(node => {
            const configured = restorable.nodes.get(node.id);
            return configured ? [{ ...configured, config: cloneConfig(configured.config) }] : [];
          }),
        }),
        value => restore(restorable, graph, value),
      );
      const state: GraphState = { ...restorable, snapshotOff };
      states.set(graphId, state);
      return state;
    };

    const currentState = () => ensureState(graphs.current.id);
    const nodeSnapshots = (): AutomationNodeSnapshot[] => {
      const state = currentState();
      return graphs.current.nodes().flatMap(node => {
        const configured = state.nodes.get(node.id);
        if (!configured) return [];
        const execution = state.execution.get(node.id) ?? { status: 'idle' as const };
        return [{ ...configured, config: cloneConfig(configured.config), ...execution }];
      });
    };
    const snapshot = (): AutomationSnapshot => ({
      types: backend.types(),
      nodes: nodeSnapshots(),
      lastRun: currentState().lastRun ? { ...currentState().lastRun!, order: [...currentState().lastRun!.order] } : null,
    });

    const syncBadges = () => {
      contexts.decorations.overlays.set(origin, nodeSnapshots().map(node => ({
        ref: nodeRef(node.id),
        id: `automation-status-${node.id}`,
        text: `${node.type} · ${node.status}`,
        className: `automation-status automation-status-${node.status}`,
      })));
    };

    const configure = ({ id, type, config }: { id: Id; type: string; config?: AutomationConfig }) => {
      if (!graphs.current.getNode(id)) return;
      const state = currentState();
      const previous = state.nodes.get(id);
      state.nodes.set(id, {
        id,
        type: type.trim(),
        config: cloneConfig(config ?? previous?.config),
      });
      state.execution.delete(id);
      state.lastRun = null;
      syncBadges();
      emit('automation.node.updated', { graphId: graphs.current.id, id, type: type.trim() });
    };

    const execute = (): AutomationRunSummary => {
      const graph = graphs.current;
      const state = currentState();
      const orderedIds = graph.nodes().map(node => node.id).filter(id => state.nodes.has(id));
      state.execution.clear();
      state.lastRun = null;
      const execution = backend.execute({
        nodes: orderedIds.map(id => state.nodes.get(id)!),
        edges: graph.edges().map(edge => ({ from: edge.From, to: edge.To })),
      });
      execution.nodes.forEach(({ id, status, input, output, error }) => {
        state.execution.set(id, { status, input, output, error });
      });
      const result: AutomationRunSummary = {
        ...execution.lastRun,
        order: execution.lastRun.order as Id[],
      };
      state.lastRun = result;
      syncBadges();
      emit('automation.run.changed', { graphId: graph.id, ...result });
      emit('app.notice', {
        message: result.status === 'success' ? `Workflow completed ${result.order.length} nodes.` : result.error!,
        level: result.status === 'success' ? 'info' : 'error',
      });
      return result;
    };

    const reset = () => {
      const state = currentState();
      state.execution.clear();
      state.lastRun = null;
      syncBadges();
      emit('automation.reset.changed', { graphId: graphs.current.id });
    };

    const createExample = () => {
      const graphId = graphs.current.id;
      const definitions = [
        { label: 'Manual Trigger', type: 'manual', config: { value: null }, x: -330, nodeType: 'user-input' as const },
        { label: 'Set Message', type: 'set', config: { value: 'hello from canvas' }, x: -110, nodeType: 'square' as const },
        { label: 'Uppercase', type: 'uppercase', config: {}, x: 110, nodeType: 'service' as const },
        { label: 'Output', type: 'output', config: {}, x: 330, nodeType: 'database' as const },
      ];
      const ids: Id[] = [];
      definitions.forEach(definition => {
        const before = new Set(graphs.current.nodes().map(node => node.id));
        emit('graph.node.create', {
          Label: { text: definition.label },
          Description: definition.type,
          NodeType: definition.nodeType,
          Position: { x: definition.x, y: 0 },
        });
        const created = graphs.current.nodes().find(node => !before.has(node.id));
        if (!created) return;
        ids.push(created.id);
        emit('automation.node.configure', { id: created.id, type: definition.type, config: definition.config });
      });
      ids.slice(1).forEach((id, index) => emit('graph.edge.create', {
        From: ids[index],
        To: id,
        EdgeKind: 'sync',
      }));
      emit('automation.example.created', { graphId, ids });
      emit('app.notice', { message: 'Automation example added. Run it from the workflow panel.' });
    };

    const inspector = () => {
      const root = document.createElement('section');
      root.className = 'automation-inspector';
      const intro = document.createElement('p');
      const current = snapshot();
      intro.className = 'automation-summary';
      intro.textContent = current.lastRun
        ? `Last run: ${current.lastRun.status} · ${current.lastRun.order.length} nodes`
        : 'Configure nodes, then run them in dependency order.';
      root.append(intro);
      current.nodes.forEach(node => {
        const row = document.createElement('article');
        row.className = 'automation-node-row';
        row.dataset.nodeId = node.id;
        row.dataset.status = node.status;
        const title = document.createElement('strong');
        title.textContent = graphs.current.getNode(node.id)!.Label.text;
        const meta = document.createElement('span');
        meta.className = 'automation-node-meta';
        meta.textContent = `${node.type} · ${node.status}`;
        row.append(title, meta);
        const result = node.error ?? display(node.output);
        if (result) {
          const output = document.createElement('code');
          output.className = node.error ? 'automation-node-error' : 'automation-node-output';
          output.textContent = result;
          row.append(output);
        }
        root.append(row);
      });
      if (!current.nodes.length) {
        const empty = document.createElement('p');
        empty.textContent = 'No automation nodes in this graph.';
        root.append(empty);
      }
      return root;
    };

    contexts.commands.register([
      { id: 'automation.example.create', label: 'Add automation example', group: 'automation' },
      { id: 'automation.run', label: 'Run workflow', group: 'automation', available: () => currentState().nodes.size > 0 },
      { id: 'automation.reset', label: 'Reset workflow status', group: 'automation', available: () => currentState().nodes.size > 0 },
      { id: 'automation.inspector.open', label: 'Open workflow inspector', group: 'automation' },
    ]);
    on('automation.node.configure', configure);
    on('automation.example.create', createExample);
    on('automation.run', execute);
    on('automation.reset', reset);
    on('automation.inspector.open', () => emit('modal.open', {
      title: 'Automation workflow',
      visual: 'properties',
      body: inspector,
    }));
    on('graph.node.deleted', ({ graphId, id }) => {
      const state = states.get(graphId);
      state?.nodes.delete(id);
      state?.execution.delete(id);
      if (graphId === graphs.current.id) syncBadges();
    });
    on('graph.created', ({ id }) => { ensureState(id); });
    on('graph.switched', ({ id }) => { ensureState(id); syncBadges(); });
    on('graph.deleted', ({ id }) => {
      states.get(id)?.snapshotOff();
      states.delete(id);
    });

    ensureState(graphs.current.id);
    declarePanel({ id: 'automation', anchor: 'middle-right', movable: true, layout: 'stack', order: 40 });
    contribute({ surface: 'top', panel: 'automation', command: 'automation.example.create', kind: 'button', text: 'Example', label: 'Add example workflow', order: 1 });
    contribute({ surface: 'top', panel: 'automation', command: 'automation.run', kind: 'button', text: 'Run', label: 'Run workflow', order: 2 });
    contribute({ surface: 'top', panel: 'automation', command: 'automation.reset', kind: 'button', text: 'Reset', label: 'Reset workflow status', order: 3 });
    contribute({ surface: 'top', panel: 'automation', command: 'automation.inspector.open', kind: 'button', text: 'Inspect', label: 'Inspect workflow run', order: 4 });

    const api: AutomationApi = {
      registerType,
      configure: (id, type, config) => emit('automation.node.configure', { id, type, config }),
      run: () => { emit('automation.run'); return currentState().lastRun; },
      reset: () => emit('automation.reset'),
      snapshot,
    };
    ctx.expose('automation', api);

    return () => {
      states.forEach(state => state.snapshotOff());
      states.clear();
    };
  }, { requires: ['graph', 'render.stage', 'tool.panel', 'modal'] });
}

import { describe, expect, it } from 'vitest';
import { bootApp, runCommand, settle } from './testkit';

describe('automation system', () => {
  it('builds and executes the example as a directed workflow', async () => {
    const ctx = bootApp();
    expect(runCommand(ctx, 'automation.example.create')).toBe(true);
    await settle();

    expect(ctx.graphs.current.nodes().map(node => node.Label.text)).toEqual([
      'Manual Trigger', 'Set Message', 'Uppercase', 'Output',
    ]);
    expect(ctx.graphs.current.edges().map(edge => [edge.From, edge.To])).toEqual([
      ['e1', 'e2'], ['e2', 'e3'], ['e3', 'e4'],
    ]);
    expect(ctx.automation?.snapshot().nodes.map(node => node.type)).toEqual([
      'manual', 'set', 'uppercase', 'output',
    ]);

    expect(runCommand(ctx, 'automation.run')).toBe(true);
    await settle();
    const run = ctx.automation!.snapshot();
    expect(run.lastRun).toEqual({ status: 'success', order: ['e1', 'e2', 'e3', 'e4'], output: 'HELLO FROM CANVAS' });
    expect(run.nodes.map(node => node.status)).toEqual(['success', 'success', 'success', 'success']);
    expect(run.nodes.at(-1)?.output).toBe('HELLO FROM CANVAS');
    expect(document.querySelectorAll('.automation-status-success')).toHaveLength(4);
  });

  it('renders the inspector and resets status without losing configuration', async () => {
    const ctx = bootApp();
    runCommand(ctx, 'automation.example.create');
    runCommand(ctx, 'automation.run');
    expect(runCommand(ctx, 'automation.inspector.open')).toBe(true);
    await settle();

    expect(document.querySelector('.automation-inspector')).not.toBeNull();
    expect(document.querySelectorAll('.automation-node-row')).toHaveLength(4);
    expect(document.body.textContent).toContain('HELLO FROM CANVAS');

    runCommand(ctx, 'automation.reset');
    await settle();
    expect(ctx.automation!.snapshot().nodes.every(node => node.status === 'idle')).toBe(true);
    expect(ctx.automation!.snapshot().nodes.find(node => node.type === 'set')?.config.value).toBe('hello from canvas');
    expect(ctx.automation!.snapshot().lastRun).toBeNull();
  });

  it('registers custom executors and reports missing executors', async () => {
    const ctx = bootApp();
    runCommand(ctx, 'automation.example.create');
    const uppercase = ctx.automation!.snapshot().nodes.find(node => node.type === 'uppercase')!;
    const unregister = ctx.automation!.registerType({
      type: 'suffix',
      label: 'Suffix',
      execute: input => `${String(input)}!`,
    });
    ctx.automation!.configure(uppercase.id, 'suffix');
    ctx.automation!.run();
    expect(ctx.automation!.snapshot().nodes.at(-1)?.output).toBe('hello from canvas!');

    unregister();
    ctx.automation!.run();
    const failed = ctx.automation!.snapshot();
    expect(failed.lastRun?.status).toBe('error');
    expect(failed.nodes.find(node => node.id === uppercase.id)?.error).toContain('Unknown automation node type');
    expect(failed.nodes.at(-1)?.status).toBe('error');
    runCommand(ctx, 'automation.inspector.open');
    await settle();
    expect(document.querySelector('.automation-node-error')?.textContent).toContain('Unknown automation node type');
  });

  it('persists plugin-owned configuration in the graph snapshot extension', async () => {
    const ctx = bootApp();
    runCommand(ctx, 'automation.example.create');
    const saved = ctx.graphs.current.snapshot();
    expect(saved.extensions?.automation).toEqual({
      version: 1,
      nodes: [
        { id: 'e1', type: 'manual', config: { value: null } },
        { id: 'e2', type: 'set', config: { value: 'hello from canvas' } },
        { id: 'e3', type: 'uppercase', config: {} },
        { id: 'e4', type: 'output', config: {} },
      ],
    });

    ctx.bus.emit('graph.import.snapshot', saved);
    await settle();
    expect(ctx.automation!.snapshot().nodes.map(node => node.type)).toEqual(['manual', 'set', 'uppercase', 'output']);
  });

  it('rejects cycles without executing their nodes', () => {
    const ctx = bootApp();
    runCommand(ctx, 'automation.example.create');
    ctx.bus.emit('graph.edge.create', { From: 'e4', To: 'e1', EdgeKind: 'sync' });
    ctx.automation!.run();

    const failed = ctx.automation!.snapshot();
    expect(failed.lastRun?.status).toBe('error');
    expect(failed.lastRun?.error).toContain('cycle');
    expect(failed.lastRun?.order).toEqual([]);
    expect(failed.nodes.every(node => node.status === 'error')).toBe(true);
  });

  it('ignores invalid configuration and malformed persisted metadata', async () => {
    const ctx = bootApp();
    ctx.automation!.configure('missing', 'set', { value: 'ignored' });
    expect(ctx.automation!.snapshot().nodes).toEqual([]);

    const snapshot = ctx.graphs.current.snapshot();
    ctx.bus.emit('graph.import.snapshot', {
      ...snapshot,
      extensions: { automation: { version: 2, nodes: [] } },
    });
    await settle();
    expect(ctx.automation!.snapshot().nodes).toEqual([]);

    const node = ctx.graphs.current.createNode({ Label: { text: 'Real' } });
    ctx.bus.emit('graph.import.snapshot', {
      ...ctx.graphs.current.snapshot(),
      extensions: {
        automation: {
          version: 1,
          nodes: [
            null,
            { id: '', type: 'set', config: {} },
            { id: node.id, type: '', config: {} },
            { id: 'missing', type: 'set', config: {} },
            { id: node.id, type: 'set', config: { value: 'kept' } },
          ],
        },
      },
    });
    await settle();
    expect(ctx.automation!.snapshot().nodes).toEqual([
      expect.objectContaining({ id: node.id, type: 'set', config: { value: 'kept' } }),
    ]);
  });

  it('renders empty and unusual inspector values', async () => {
    const empty = bootApp();
    runCommand(empty, 'automation.inspector.open');
    await settle();
    expect(document.body.textContent).toContain('Configure nodes');
    expect(document.body.textContent).toContain('No automation nodes');

    const ctx = bootApp();
    runCommand(ctx, 'automation.example.create');
    const configured = ctx.automation!.snapshot().nodes;
    const circular: Record<string, unknown> = {};
    circular.self = circular;
    ctx.automation!.registerType({ type: 'object', label: 'Object', execute: () => ({ ok: true }) });
    ctx.automation!.registerType({ type: 'circular', label: 'Circular', execute: () => circular });
    ctx.automation!.registerType({ type: 'nothing', label: 'Nothing', execute: () => undefined });
    ctx.automation!.configure(configured[0].id, 'object');
    ctx.automation!.configure(configured[1].id, 'circular');
    ctx.automation!.configure(configured[2].id, 'nothing');
    ctx.automation!.run();
    runCommand(ctx, 'automation.inspector.open');
    await settle();
    expect(document.body.textContent).toContain('{"ok":true}');
    expect(document.body.textContent).toContain('[object Object]');
  });

  it('tracks graph and node lifecycle and disposes its snapshot registrations', async () => {
    const ctx = bootApp();
    runCommand(ctx, 'automation.example.create');
    ctx.bus.emit('graph.node.delete', { id: 'e1' });
    expect(ctx.automation!.snapshot().nodes.some(node => node.id === 'e1')).toBe(false);
    ctx.bus.emit('graph.node.deleted', { graphId: 'not-loaded', id: 'none' });
    ctx.bus.emit('graph.created', { id: 'not-loaded' });
    ctx.bus.emit('graph.deleted', { id: 'not-loaded', nextId: ctx.graphs.current.id });

    const original = ctx.graphs.current.id;
    runCommand(ctx, 'graph.create');
    const second = ctx.graphs.current.id;
    expect(second).not.toBe(original);
    expect(ctx.automation!.snapshot().nodes).toEqual([]);
    ctx.bus.emit('graph.node.deleted', { graphId: original, id: 'e2' });
    ctx.bus.emit('graph.switch', { id: original });
    expect(ctx.automation!.snapshot().nodes.some(node => node.id === 'e2')).toBe(false);
    ctx.bus.emit('graph.delete', { id: second });

    ctx.automation!.reset();
    ctx.registry!.stop(ctx, 'automation');
    expect(ctx.contexts.commands.get('automation.run')).toBeUndefined();
  });

  it('handles an unavailable graph creator without partial example state', () => {
    const ctx = bootApp({ dx: false });
    ctx.registry!.stop(ctx, 'graph');
    expect(runCommand(ctx, 'automation.example.create')).toBe(true);
    expect(ctx.automation!.snapshot().nodes).toEqual([]);
  });
});

import { describe, expect, it } from 'vitest';
import { AutomationBackend, createAutomationBackend, executeAutomation } from '../../backend/automation';

const workflow = {
  nodes: [
    { id: 'trigger', type: 'manual', config: { value: null } },
    { id: 'set', type: 'set', config: { value: 'hello from backend' } },
    { id: 'upper', type: 'uppercase', config: {} },
    { id: 'sink', type: 'output', config: {} },
  ],
  edges: [
    { from: 'trigger', to: 'set' },
    { from: 'set', to: 'upper' },
    { from: 'upper', to: 'sink' },
  ],
};

describe('headless automation backend', () => {
  it('executes a workflow without DOM or canvas state', () => {
    const result = executeAutomation(workflow);
    expect(result.lastRun).toEqual({
      status: 'success',
      order: ['trigger', 'set', 'upper', 'sink'],
      output: 'HELLO FROM BACKEND',
    });
    expect(result.nodes.map(node => node.status)).toEqual(['success', 'success', 'success', 'success']);
  });

  it('supports server-owned custom node registries', () => {
    const backend = createAutomationBackend();
    const unregister = backend.registerType({
      type: 'suffix',
      label: 'Suffix',
      execute: (input, config) => `${String(input)}${String(config.value)}`,
    });
    const result = backend.execute({
      nodes: [
        { id: 'start', type: 'set', config: { value: 'ready' } },
        { id: 'finish', type: 'suffix', config: { value: '!' } },
      ],
      edges: [{ from: 'start', to: 'finish' }],
    });
    expect(result.lastRun.output).toBe('ready!');
    unregister();
    expect(backend.types()).not.toContain('suffix');
  });

  it('reports missing types and blocks downstream work', () => {
    const backend = new AutomationBackend();
    const result = backend.execute({
      nodes: [
        { id: 'missing', type: 'not-installed' },
        { id: 'blocked', type: 'also-missing' },
      ],
      edges: [{ from: 'missing', to: 'blocked' }],
    });
    expect(result.lastRun.status).toBe('error');
    expect(result.nodes[0].error).toContain('Unknown automation node type');
    expect(result.nodes[1].error).toContain('Blocked by failed node');
  });

  it('rejects cycles deterministically', () => {
    const backend = createAutomationBackend();
    const result = backend.execute({
      nodes: [
        { id: 'a', type: 'manual' },
        { id: 'b', type: 'output' },
      ],
      edges: [{ from: 'a', to: 'b' }, { from: 'b', to: 'a' }],
    });
    expect(result.lastRun).toMatchObject({ status: 'error', order: [], error: expect.stringContaining('cycle') });
    expect(result.nodes.every(node => node.status === 'error')).toBe(true);
  });

  it('validates registrations and restores shadowed definitions safely', () => {
    const backend = new AutomationBackend();
    expect(() => backend.registerType({ type: '  ', label: 'Bad', execute: () => null })).toThrow('must not be empty');

    const removeFirst = backend.registerType({ type: ' value ', label: 'First', execute: () => 'first' });
    const removeSecond = backend.registerType({ type: 'value', label: 'Second', execute: () => 'second' });
    removeFirst();
    expect(backend.execute({ nodes: [{ id: 'x', type: 'value' }], edges: [] }).lastRun.output).toBe('second');
    removeSecond();
    expect(backend.execute({ nodes: [{ id: 'x', type: 'value' }], edges: [] }).lastRun.output).toBe('first');
    removeFirst();
    expect(backend.types()).not.toContain('value');
  });

  it('handles empty workflows, irrelevant edges, and deterministic parallel roots', () => {
    const backend = createAutomationBackend();
    expect(backend.execute({ nodes: [], edges: [] }).lastRun.error).toContain('No automation nodes');
    const result = backend.execute({
      nodes: [
        { id: 'right', type: 'set', config: { value: 'R' } },
        { id: 'left', type: 'set', config: { value: 'L' } },
        { id: 'join', type: 'output' },
      ],
      edges: [
        { from: 'missing', to: 'join' },
        { from: 'left', to: 'join' },
        { from: 'right', to: 'join' },
      ],
    });
    expect(result.lastRun.order).toEqual(['right', 'left', 'join']);
    expect(result.lastRun.output).toEqual(['L', 'R']);
  });

  it('turns async and thrown executor failures into node errors', () => {
    const backend = createAutomationBackend();
    backend.registerType({ type: 'async', label: 'Async', execute: async () => 'later' });
    backend.registerType({ type: 'error', label: 'Error', execute: () => { throw new Error('boom'); } });
    backend.registerType({ type: 'string-error', label: 'String error', execute: () => { throw 'plain failure'; } });

    expect(backend.execute({ nodes: [{ id: 'x', type: 'async' }], edges: [] }).nodes[0].error).toContain('Async executors');
    expect(backend.execute({ nodes: [{ id: 'x', type: 'error' }], edges: [] }).nodes[0].error).toBe('boom');
    expect(backend.execute({ nodes: [{ id: 'x', type: 'string-error' }], edges: [] }).nodes[0].error).toBe('plain failure');
  });

  it('covers nullable built-in inputs', () => {
    const result = executeAutomation({ nodes: [{ id: 'upper', type: 'uppercase' }], edges: [] });
    expect(result.lastRun.output).toBe('');
  });
});

